// The bundled brushes made by us (Phase 19, SPEC 1.3.1). Pure data: no Vite
// features, so Node scripts and tests can import it. The tip and grain PNGs
// these reference are generated by frontend/scripts/brushgen.ts.
//
// Every brush is hand-tuned (spacing, scatter, rotation, dynamics, wet values)
// so that each has its own quality; `mk` fills the rest from BASE.
import {
  BRUSH_SCHEMA_VERSION,
  type BrushPreset,
  type ColorDynamics,
  type Curve,
  type Dynamics,
  type DynamicsInput,
  type DynamicsTarget,
  type Grain,
  type Smoothing,
  type Tip,
  type Wet,
} from "../schema";

export const SET_NAMES = [
  "Sketching",
  "Inking",
  "Painting",
  "Airbrush",
  "Nature",
  "Texture",
  "Elements",
  "Pixel",
  "Erasers",
  "Smudge",
] as const;
export type SetName = (typeof SET_NAMES)[number];

const BASE: BrushPreset = {
  version: BRUSH_SCHEMA_VERSION,
  id: "",
  name: "",
  set: "",
  size: 24,
  minSize: 0.2,
  opacity: 1,
  flow: 1,
  spacing: 0.1,
  scatter: 0,
  count: 1,
  taper: { start: 0, end: 0, byPressure: false },
  tip: { shape: "round", hardness: 1, roundness: 1, angle: 0, angleMode: "fixed", rotationJitter: 0, invert: false },
  dual: null,
  grain: { texture: "", mode: "moving", scale: 1, depth: 0, contrast: 1 },
  dynamics: [],
  color: { hueJitter: 0, satJitter: 0, briJitter: 0, perStroke: false, secondaryMix: 0 },
  wet: { mix: 0, dilution: 0, charge: 0, pull: 0, grade: 0, edges: 0, bleed: 0 },
  rendering: "light-glaze",
  impasto: 0,
  blend: "normal",
  smoothing: { streamline: 0.2, stabilisation: 0, motionFilter: 0 },
  antialias: true,
  credit: "",
  license: "",
  fidelity: [],
};

type Spec = Partial<
  Omit<BrushPreset, "id" | "name" | "set" | "version" | "tip" | "grain" | "wet" | "color" | "smoothing" | "taper" | "credit" | "license" | "fidelity">
> & {
  tip?: Partial<Tip>;
  grain?: Partial<Grain>;
  wet?: Partial<Wet>;
  color?: Partial<ColorDynamics>;
  smoothing?: Partial<Smoothing>;
  taper?: Partial<BrushPreset["taper"]>;
};

export function slug(s: string): string {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

function mk(set: SetName, name: string, s: Spec): BrushPreset {
  const { tip, grain, wet, color, smoothing, taper, ...rest } = s;
  return {
    ...BASE,
    ...rest,
    id: slug(`${set} ${name}`),
    name,
    set,
    tip: { ...BASE.tip, ...tip },
    grain: { ...BASE.grain, ...grain },
    wet: { ...BASE.wet, ...wet },
    color: { ...BASE.color, ...color },
    smoothing: { ...BASE.smoothing, ...smoothing },
    taper: { ...BASE.taper, ...taper },
    dynamics: rest.dynamics ?? [],
  };
}

// ---- helpers ----
const LIN: Curve = [[0, 0], [1, 1]];
const SOFT: Curve = [[0, 0], [0.25, 0.55], [1, 1]];
const FIRM: Curve = [[0, 0], [0.55, 0.3], [1, 1]];
const INV: Curve = [[0, 1], [1, 0]];

const d = (input: DynamicsInput, target: DynamicsTarget, amount: number, curve: Curve = LIN): Dynamics => ({ input, target, amount, curve });
const tp = (name: string, extra: Partial<Tip> = {}): Partial<Tip> => ({ shape: `lib:tips/${name}.png`, ...extra });
const gr = (name: string, extra: Partial<Grain> = {}): Partial<Grain> => ({ texture: `lib:grains/${name}.png`, ...extra });

