// ---- Nature ----
function leafBrush(name: string, tipName: string, o: Spec): BrushPreset {
  return mk("Nature", name, {
    spacing: 0.55, scatter: 0.6, tip: tp(tipName, { ...STROKE, rotationJitter: 0.35 }),
    dynamics: [d("pressure", "size", 0.4)], taper: { end: 0.3 }, ...o,
  });
}
